import json, os, glob, re, sys

ROOT = os.path.expanduser("~/.claude/projects/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa")

def text_of(msg):
    c = msg.get("content")
    if isinstance(c, str): return c
    if isinstance(c, list):
        return " ".join(p.get("text","") for p in c if isinstance(p, dict) and p.get("type")=="text")
    return ""

rows = []
for f in glob.glob(os.path.join(ROOT, "*.jsonl")):
    title = None; first = None; nturns = 0; mtime = os.path.getmtime(f)
    try:
        for line in open(f, errors="ignore"):
            line = line.strip()
            if not line: continue
            try: d = json.loads(line)
            except: continue
            t = d.get("type")
            if t == "custom-title" and not title: title = d.get("customTitle")
            elif t == "ai-title" and not title: title = d.get("aiTitle")
            elif t == "user":
                if d.get("isSidechain"): continue
                nturns += 1
                if first is None:
                    txt = text_of(d.get("message", {}))
                    txt = re.sub(r"<[^>]+>", " ", txt)          # strip tags
                    txt = re.sub(r"\s+", " ", txt).strip()
                    if txt and not txt.startswith("Caveat:"): first = txt[:300]
    except Exception as e:
        continue
    if first or title:
        rows.append((mtime, title or "(untitled)", nturns, first or ""))

rows.sort(reverse=True)
print(f"TOTAL SESSIONS WITH CONTENT: {len(rows)}\n")
for mt, title, n, first in rows:
    import datetime
    ds = datetime.datetime.fromtimestamp(mt).strftime("%m-%d")
    print(f"[{ds}] ({n:3d}t) {title}\n      {first}\n")
PY
